import Foundation

/// Langues proposées (sélection in-app, indépendante de la langue système).
enum AppLanguage: String, CaseIterable, Codable, Identifiable {
    case fr, en, es, it, de
    var id: String { rawValue }
    var flag: String { ["fr": "🇫🇷", "en": "🇬🇧", "es": "🇪🇸", "it": "🇮🇹", "de": "🇩🇪"][rawValue]! }
    var name: String { ["fr": "Français", "en": "English", "es": "Español", "it": "Italiano", "de": "Deutsch"][rawValue]! }

    static func systemDefault() -> AppLanguage {
        let code = Locale.preferredLanguages.first?.prefix(2).lowercased() ?? "en"
        return AppLanguage(rawValue: String(code)) ?? .en
    }
}

/// Traductions. Clé = texte français ; valeurs = [en, es, it, de]. Repli sur le français si absent.
